fn frame(t: i32) {
    host::display::clear(0x101216);
    let own: i32 = host::agent::viewer_is_owner();
    let subbed: i32 = host::agent::is_subscribed();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    let mut click: i32 = 0;
    if down == 1 && prev == 0 {
        click = 1;
    }
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();

    host::display::draw_string(140, 40, "ANNOUNCEMENTS", 0xffffff, 2);
    host::display::draw_string(150, 90, "SUBSCRIBERS", 0x556677, 1);
    host::display::draw_number(250, 86, host::agent::subscriber_count(), 0xffffff, 2);

    if own == 1 {
        host::display::fill_rect(106, 160, 300, 100, 0xdddddd);
        host::display::draw_string(158, 196, "ANNOUNCE...", 0x000000, 2);
        host::display::draw_string(106, 290, "OPENS THE HOST COMPOSER SO YOU", 0x666677, 1);
        host::display::draw_string(106, 304, "CAN TYPE THE MESSAGE FIRST", 0x666677, 1);
        if click == 1 && px >= 106 && px < 406 && py >= 160 && py < 260 {
            host::agent::broadcast_compose("Announcement", "Something new just shipped.");
        }
    } else {
        let mut col: i32 = 0x222a33;
        if subbed == 1 {
            col = 0x1a5c2a;
        }
        host::display::fill_rect(106, 160, 300, 100, col);
        if subbed == 1 {
            host::display::draw_string(126, 196, "GETTING UPDATES", 0x99ffbb, 2);
        } else {
            host::display::draw_string(146, 196, "GET UPDATES", 0xffffff, 2);
        }
        host::display::draw_string(106, 290, "ONLY THE OWNER CAN ANNOUNCE", 0x666677, 1);
        if click == 1 && px >= 106 && px < 406 && py >= 160 && py < 260 {
            if subbed == 1 {
                host::agent::unsubscribe();
            } else {
                host::agent::subscribe();
            }
        }
    }
    host::display::present();
}
